<?php
require_once '../config/db.php'; require_once '../includes/auth.php'; require_role(['Admin','Property Officer']);
$properties=$pdo->query("SELECT p.id,p.property_code,p.property_no,p.scheme_name,p.price,a.allottee_name,a.allotment_date,COALESCE(SUM(pp.amount),0) total_paid FROM properties p JOIN allottees a ON a.property_id=p.id LEFT JOIN property_payments pp ON pp.property_id=p.id GROUP BY p.id,p.property_code,p.property_no,p.scheme_name,p.price,a.allottee_name,a.allotment_date HAVING total_paid >= p.price ORDER BY a.allotment_date DESC")->fetchAll();
?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Registry Entry</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/css/style.css" rel="stylesheet"></head><body><div class="portal-wrapper"><header class="portal-header"><div class="portal-brand">📜 Registry Entry</div><div class="portal-header-actions"><a href="admin.php" class="btn btn-sm btn-outline-light">Dashboard</a><a href="../logout.php" class="btn btn-sm btn-light">Logout</a></div></header><main class="portal-main"><div class="portal-page-header"><h1 class="portal-page-title">Registry Ready Properties</h1><p class="portal-page-subtitle">Jinka pura payment receive ho gaya hai, unki registry entry yahan dikhegi.</p></div><div class="dashboard-shell table-responsive"><table class="table align-middle"><thead><tr><th>S.No.</th><th>Property</th><th>Scheme</th><th>Allottee</th><th>Allotment Date</th><th>Total Cost</th><th>Paid</th><th>Action</th></tr></thead><tbody><?php foreach($properties as $i=>$p): ?><tr><td><?= $i+1 ?></td><td><?= htmlspecialchars($p['property_code']) ?><br><?= htmlspecialchars($p['property_no']) ?></td><td><?= htmlspecialchars($p['scheme_name']) ?></td><td><?= htmlspecialchars($p['allottee_name']) ?></td><td><?= htmlspecialchars($p['allotment_date']?:'-') ?></td><td>₹<?= number_format($p['price'],2) ?></td><td class="text-success fw-bold">₹<?= number_format($p['total_paid'],2) ?></td><td><a href="property_detail.php?id=<?= $p['id'] ?>" class="btn btn-sm btn-primary">Open Detail</a></td></tr><?php endforeach; ?><?php if(!$properties): ?><tr><td colspan="8" class="text-center text-muted">No fully paid property is ready for registry.</td></tr><?php endif; ?></tbody></table></div></main></div></body></html>
